# ONE READ THIS BLOCK WOULD MAKE, answered by the rows the page read once for its head, its frame
# and its blocks: `{:ok, rows}` where the page read exactly that, as this reader, and `:error` where
# it did not, so the block reads it itself.
#
#   * `{:record, kind, slug, language}` — the post, category or tag the page's slug names in its
#     language, or the blogger or team (`:any` language: one row in every language); `nil` where
#     the reader's read found none;
#   * `{:featured, limit, language}` — the front page's newest featured posts;
#   * `{:total, category, tag, language}` — how many posts the reader may open in the language, of
#     the category or the tag the page is of, or of none on the front page;
#   * `{:listed, category, tag, left_out, per_page, page, language}` — the page of the list the page
#     draws first, newest first, with what each card is drawn from: of the category or the tag the
#     page is of, or on the front page of every post but the `left_out` newest featured ones.
case {source, read} do
  {%{kind: kind, slug: slug, language: language, record: record}, {:record, kind, slug, language}}
  when kind != "blog:home" ->
    {:ok, record}

  {%{kind: kind, slug: slug, record: record}, {:record, kind, slug, :any}}
  when kind in ["blog:author", "blog:team"] ->
    {:ok, record}

  {%{kind: "blog:home", language: language, featured: %{limit: limit, rows: rows}},
   {:featured, limit, language}} ->
    {:ok, rows}

  {%{kind: "blog:home", language: language, total: total}, {:total, "", "", language}}
  when is_integer(total) ->
    {:ok, total}

  {%{kind: "blog:category", slug: slug, language: language, record: %{listed_post_count: total}},
   {:total, slug, "", language}}
  when is_integer(total) ->
    {:ok, total}

  {%{kind: "blog:tag", slug: slug, language: language, record: %{listed_post_count: total}},
   {:total, "", slug, language}}
  when is_integer(total) ->
    {:ok, total}

  {%{
     kind: "blog:home",
     language: language,
     featured: %{limit: left_out},
     listed: %{per_page: per_page, page: page, rows: rows}
   }, {:listed, "", "", left_out, per_page, page, language}} ->
    {:ok, rows}

  {%{
     kind: "blog:category",
     slug: slug,
     language: language,
     listed: %{per_page: per_page, page: page, rows: rows}
   }, {:listed, slug, "", 0, per_page, page, language}} ->
    {:ok, rows}

  {%{
     kind: "blog:tag",
     slug: slug,
     language: language,
     listed: %{per_page: per_page, page: page, rows: rows}
   }, {:listed, "", slug, 0, per_page, page, language}} ->
    {:ok, rows}

  _not_read_for_this ->
    :error
end

# A TUPLE RATHER THAN A LIST, and that is what the error state is built on: folding an unreadable
# answer into an empty one leaves a block telling a reader that nothing is published when the truth
# is that nothing could be read.
case result do
  {:ok, %{results: found, count: count}} -> {:ok, %{rows: found, total: count || length(found)}}
  {:ok, found} when is_list(found) -> {:ok, %{rows: found, total: length(found)}}
  {:error, reason} -> {:error, reason}
  _unreadable -> {:error, :unreadable}
end

