# RUN IN THE TASK, so nothing here may touch the socket — and nothing here builds an address,
# because `site_path/2` answers for the site the page's own process renders for.
with {:ok, teams} <- teams(asked),
     {:ok, unteamed} <- unteamed(asked) do
  {:ok,
   %{
     teams:
       Enum.map(teams, fn team ->
         %{
           id: team.id,
           name: team.name,
           slug: team.slug,
           image: team.avatar_url,
           about: team.description,
           members: Enum.map(team.members, fn member -> person(member) end)
         }
       end),
     unteamed: Enum.map(unteamed, fn blogger -> person(blogger) end)
   }}
end

# A PICTURE, OR THEIR LETTERS ON A TINT, at one size. It is markup rather than a component of its own
# because three blocks draw it and none of them can be dropped into the others, and because the
# seventeen components this bundle ships are the ones a page can name. `stacked` overlaps it with the
# next one and rings it in the surface colour, which is how the design draws a team's faces.
#
# THIS IS WHERE A PERSON'S COLOUR IS DECIDED, once, for every page that draws them: the byline of a
# card, the head of a post, a blogger's own page. `class` is only for the size `custom` leaves to the
# caller, so a face is never given a tint of the caller's own.
assigns = Phoenix.Component.assign_new(assigns, :class, fn -> nil end)

~H"""
<img
  :if={trimmed(@image) != ""}
  src={@image}
  alt={@alt}
  data-role="blog-profile-image"
  class={[
    "flex-none rounded-full object-cover",
    box(@size),
    @class,
    @stacked && "-me-2.5 border-2 border-surface dark:border-surface-dark"
  ]}
/>

<span
  :if={trimmed(@image) == ""}
  aria-hidden="true"
  data-role="blog-profile-initial"
  class={[
    "flex flex-none items-center justify-center rounded-full",
    box(@size),
    lettering(@size),
    tint(@seed),
    @class,
    @stacked && "-me-2.5 border-2 border-surface dark:border-surface-dark"
  ]}
>
  {initials(@name)}
</span>
"""
